effect.shader:
#define EPS 0.00001
#define PI 3.14159265359
vec3 toLinear(vec3 s) {
    vec3 lo = s / 12.92;
    vec3 hi = pow((s + 0.055) / 1.055, vec3(2.4));
    return mix(lo, hi, step(vec3(0.04045), s));
}
vec3 toSRGB(vec3 l) {
    vec3 lo = l * 12.92;
    vec3 hi = 1.055 * pow(max(l, 0.0), vec3(1.0 / 2.4)) - 0.055;
    return mix(lo, hi, step(vec3(0.0031308), l));
}
float lum(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}
vec3 rgb2hsl(vec3 c) {
    float mx = max(c.r, max(c.g, c.b));
    float mn = min(c.r, min(c.g, c.b));
    float l = (mx + mn) * 0.5;
    float d = mx - mn;
    float s = 0.0;
    float h = 0.0;
    if (d > EPS) {
        s = (l > 0.5) ? d / max(2.0 - mx - mn, EPS) : d / max(mx + mn, EPS);
        if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
        else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
        else { h = (c.r - c.g) / d + 4.0; }
        h /= 6.0;
    }
    return vec3(h, s, l);
}
float h2r(float p, float q, float t) {
    if (t < 0.0) t += 1.0;
    if (t > 1.0) t -= 1.0;
    if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
    if (t < 0.5) return q;
    if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    return p;
}
vec3 hsl2rgb(vec3 c) {
    if (c.y < EPS) return vec3(c.z);
    float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
    float p = 2.0 * c.z - q;
    return vec3(h2r(p,q,c.x+1.0/3.0), h2r(p,q,c.x), h2r(p,q,c.x-1.0/3.0));
}
float getTaps(float q) {
    if (q < 1.5) return 10.0;
    if (q < 2.5) return 18.0;
    return 28.0;
}
vec4 separableBlur(sampler2D tex, vec2 uv, vec2 dir, float radius, float taps) {
    if (radius <= 0.5) return texture2DCv(tex, uv);
    float sigma = radius / 2.14596602;
    sigma = max(sigma, EPS);
    float baseCoeff = 1.0 / (sqrt(2.0 * PI) * sigma);
    float decayRate = exp(-0.5 / (sigma * sigma));
    float decaySq = decayRate * decayRate;
    vec4 acc = texture2DCv(tex, uv) * baseCoeff;
    float wSum = baseCoeff;
    float coeff = baseCoeff;
    float decay = decayRate;
    for (float i = 1.0; i <= 256.0; i += 2.0) {
        if (i > taps) break;
        float p0 = i;
        float p1 = i + 1.0;
        coeff *= decay;
        wSum += 2.0 * coeff;
        float w0 = coeff;
        coeff *= decay;
        decay *= decaySq;
        wSum += 2.0 * coeff;
        float w1 = coeff;
        float wPair = w0 + w1;
        float oPair = (p0 * w0 + p1 * w1) / max(wPair, EPS);
        vec2 uvA = clamp(uv - oPair * dir, 0.0, 1.0);
        vec2 uvB = clamp(uv + oPair * dir, 0.0, 1.0);
        acc += texture2DCv(tex, uvA) * wPair;
        acc += texture2DCv(tex, uvB) * wPair;
    }
    return acc / max(wSum, EPS);
}
void main() {
    vec2 uv = acScreenNorm;
    float taps = getTaps(float(quality));
    float r1 = diffRadius * 0.5;
    float r2 = diffRadius * 1.5;
    if (acPass == 0) {
        vec2 dir = vec2(1.0 / getTexSize(inputImg.size).x, 0.0);
        gl_FragColor = separableBlur(inputImg.texture, uv, dir, r1, taps);
        return;
    }
    if (acPass == 1) {
        vec2 dir = vec2(0.0, 1.0 / getTexSize(blurA.size).y);
        gl_FragColor = separableBlur(blurA.texture, uv, dir, r1, taps);
        return;
    }
    if (acPass == 2) {
        vec2 dir = vec2(1.0 / getTexSize(inputImg.size).x, 0.0);
        gl_FragColor = separableBlur(inputImg.texture, uv, dir, r2, taps);
        return;
    }
    if (acPass == 3) {
        vec2 dir = vec2(0.0, 1.0 / getTexSize(blurC.size).y);
        gl_FragColor = separableBlur(blurC.texture, uv, dir, r2, taps);
        return;
    }
    vec4 original = texture2DCv(inputImg.texture, uv);
    vec3 baseRGB = max(original.rgb, 0.0);
    vec3 sharp = baseRGB;
    vec3 softNarrow = max(texture2DCv(blurB.texture, uv).rgb, 0.0);
    vec3 softWide = max(texture2DCv(blurD.texture, uv).rgb, 0.0);
    vec3 baseLin = toLinear(baseRGB);
    vec3 narrowLin = toLinear(softNarrow);
    vec3 wideLin = toLinear(softWide);
    float baseLum = lum(baseLin);
    float narrowLum = lum(narrowLin);
    float wideLum = lum(wideLin);
    vec3 diffused = mix(narrowLin, wideLin, diffSoftness);
    float diffLum = lum(diffused);
    vec3 result = mix(baseLin, diffused, diffAmount * diffCharacter);
    vec3 screenBlend = 1.0 - (1.0 - baseLin) * (1.0 - diffused * 0.5);
    result = mix(result, screenBlend, diffAmount * (1.0 - diffCharacter));
    if (hlDiffusion > EPS) {
        float hlMask = smoothstep(hlThreshold - 0.1, hlThreshold + 0.1, baseLum);
        vec3 hlBlur = wideLin * hlMask;
        if (abs(hlSaturation - 1.0) > EPS) {
            float hlL = lum(hlBlur);
            hlBlur = mix(vec3(hlL), hlBlur, hlSaturation);
        }
        result += hlBlur * hlDiffusion * 0.5;
        if (hlWrap > EPS) {
            float wrapMask = smoothstep(hlThreshold, hlThreshold + 0.3, baseLum);
            vec3 wrapped = mix(result, wideLin, wrapMask * hlWrap * 0.3);
            result = wrapped;
        }
    }
    if (shDiffusion > EPS) {
        float shMask = smoothstep(shThreshold + 0.1, shThreshold - 0.1, baseLum);
        vec3 shBlur = mix(baseLin, diffused, shMask * shDiffusion);
        result = mix(result, shBlur, shMask * shDiffusion * 0.5);
        if (shLift > EPS) {
            result += shLift * shMask;
        }
    }
    if (halStrength > EPS) {
        vec3 halSource = mix(narrowLin, wideLin, clamp(halRadius - 1.0, 0.0, 1.0));
        float halLum = lum(halSource);
        float halMask = smoothstep(0.4, 0.8, halLum);
        vec3 halation = halSource * halColor.rgb * halMask;
        result += halation * halStrength * 0.4;
    }
    if (ortonStrength > EPS) {
        vec3 ortonBright = pow(max(baseLin, 0.0), vec3(ortonGamma));
        vec3 ortonBlur = diffused;
        vec3 ortonMul = ortonBright * ortonBlur * 4.0;
        vec3 ortonResult = mix(ortonBlur, ortonMul, ortonContrast);
        result = mix(result, ortonResult, ortonStrength * 0.5);
    }
    if (chromaDiff > EPS) {
        float cAng = chromaAngle * PI / 180.0;
        vec2 cDir = vec2(cos(cAng), sin(cAng));
        vec2 cPx = 1.0 / getTexSize(blurD.size);
        vec2 cOff = cDir * chromaDiff * 3.0 * cPx;
        float rCh = max(texture2DCv(blurD.texture, clamp(uv + cOff, 0.0, 1.0)).r, 0.0);
        float bCh = max(texture2DCv(blurD.texture, clamp(uv - cOff, 0.0, 1.0)).b, 0.0);
        float origR = result.r;
        float origB = result.b;
        result.r = mix(origR, toLinear(vec3(rCh)).r, chromaDiff * 0.3);
        result.b = mix(origB, toLinear(vec3(bCh)).b, chromaDiff * 0.3);
    }
    if (fogAmount > EPS) {
        vec3 fogLin = toLinear(fogColor.rgb);
        float fogMask = mix(1.0, baseLum, fogHighlightBias);
        fogMask = pow(max(fogMask, 0.0), 1.0 + fogDensity * 2.0);
        result = mix(result, fogLin, fogAmount * fogMask * 0.3);
    }
    if (dreamStrength > EPS) {
        vec3 dreamBase = mix(narrowLin, wideLin, 0.7);
        float dreamLum = lum(dreamBase);
        vec3 dreamDesat = mix(dreamBase, vec3(dreamLum), dreamDesaturation);
        if (abs(dreamWarmth) > EPS) {
            dreamDesat.r += dreamWarmth * 0.08;
            dreamDesat.b -= dreamWarmth * 0.05;
        }
        vec3 dreamScreen = 1.0 - (1.0 - result) * (1.0 - dreamDesat * 0.4);
        result = mix(result, dreamScreen, dreamStrength * 0.6);
    }
    if (skinSmooth > EPS) {
        vec3 skinTest = rgb2hsl(max(baseRGB, 0.0));
        float hueDist = abs(skinTest.x - skinHueCenter);
        hueDist = min(hueDist, 1.0 - hueDist);
        float skinMask = smoothstep(skinHueRange, skinHueRange * 0.3, hueDist);
        skinMask *= smoothstep(0.15, 0.35, skinTest.y);
        skinMask *= smoothstep(0.1, 0.3, skinTest.z) * (1.0 - smoothstep(0.8, 0.95, skinTest.z));
        if (skinMask > EPS) {
            float detailEdge = abs(baseLum - narrowLum) * 5.0;
            float detailPreserve = clamp(detailEdge / max(skinDetail, EPS), 0.0, 1.0);
            float smoothMask = skinMask * skinSmooth * (1.0 - detailPreserve);
            result = mix(result, narrowLin, smoothMask * 0.6);
        }
    }
    if (contrastRestore > EPS) {
        float rLum = lum(result);
        float contrast = (rLum - 0.5) * contrastRestore * 0.5;
        float midMask = 1.0 - abs(rLum - 0.5) * 2.0;
        midMask = pow(max(midMask, 0.0), 1.0 - midtoneProtect);
        result += contrast * (1.0 - midMask * midtoneProtect);
    }
    if (blackPoint > EPS) {
        result = max(result - blackPoint, 0.0) / max(1.0 - blackPoint, EPS);
    }
    if (abs(saturation - 1.0) > EPS) {
        float rL = lum(result);
        result = mix(vec3(rL), result, saturation);
    }
    if (abs(warmth) > EPS) {
        result.r += warmth * 0.06;
        result.b -= warmth * 0.04;
    }
    if (diffTintStrength > EPS) {
        vec3 tintLin = toLinear(diffTint.rgb);
        result = mix(result, result * tintLin, diffTintStrength);
    }
    vec3 blendResult = result;
    float bm = float(blendMode);
    if (bm < 1.5) {
        blendResult = result;
    } else if (bm < 2.5) {
        blendResult = 1.0 - (1.0 - baseLin) * (1.0 - result * 0.5);
    } else if (bm < 3.5) {
        vec3 bS = toSRGB(baseLin);
        vec3 gS = toSRGB(clamp(result, 0.0, 1.0));
        vec3 r;
        r.r = (gS.r<0.5) ? 2.0*bS.r*gS.r+bS.r*bS.r*(1.0-2.0*gS.r) : 2.0*bS.r*(1.0-gS.r)+sqrt(max(bS.r,0.0))*(2.0*gS.r-1.0);
        r.g = (gS.g<0.5) ? 2.0*bS.g*gS.g+bS.g*bS.g*(1.0-2.0*gS.g) : 2.0*bS.g*(1.0-gS.g)+sqrt(max(bS.g,0.0))*(2.0*gS.g-1.0);
        r.b = (gS.b<0.5) ? 2.0*bS.b*gS.b+bS.b*bS.b*(1.0-2.0*gS.b) : 2.0*bS.b*(1.0-gS.b)+sqrt(max(bS.b,0.0))*(2.0*gS.b-1.0);
        blendResult = toLinear(r);
    } else {
        vec3 bS = toSRGB(baseLin);
        vec3 gS = toSRGB(clamp(result, 0.0, 1.0));
        vec3 r;
        r.r = (bS.r<0.5) ? 2.0*bS.r*gS.r : 1.0-2.0*(1.0-bS.r)*(1.0-gS.r);
        r.g = (bS.g<0.5) ? 2.0*bS.g*gS.g : 1.0-2.0*(1.0-bS.g)*(1.0-gS.g);
        r.b = (bS.b<0.5) ? 2.0*bS.b*gS.b : 1.0-2.0*(1.0-bS.b)*(1.0-gS.b);
        blendResult = toLinear(r);
    }
    vec3 fin = toSRGB(max(blendResult, 0.0));
    if (ditherAmt > EPS) {
        vec2 px = floor(getTexSize(inputImg.size) * uv);
        float n1 = fract(sin(dot(px, vec2(12.9898, 78.233))) * 43758.5453);
        float n2 = fract(sin(dot(px, vec2(24.123, 17.321))) * 12345.6789);
        float n3 = fract(sin(dot(px, vec2(93.989, 67.345))) * 98765.4321);
        fin += (vec3(n1, n2, n3) - 0.5) * ditherAmt;
    }
    if (diffOnly) {
        vec3 diffOnlyRGB = toSRGB(max(result - baseLin, 0.0));
        gl_FragColor = vec4(clamp(diffOnlyRGB, 0.0, 1.0), 1.0);
        return;
    }
    fin = mix(baseRGB, fin, globalMix);
    fin = clamp(fin, 0.0, 1.0);
    gl_FragColor = vec4(fin, original.a);
}
